head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// Drag 전후로 클릭하여 각 Column 의 현재 너비를 비교한다
scwin.btn_checkWidth_onclick = function (e) {
    var objGrid = $p.getComponentById("target1");
    scwin.setReturnValue("=====현재 컬럼 너비=====");
    scwin.setReturnValue("RowNum : " + objGrid.getColumnWidth(0) + "px");
    scwin.setReturnValue("RowStatus : " + objGrid.getColumnWidth(1) + "px");
    scwin.setReturnValue("col1 (minWidth=120 / 초기 180) : " + objGrid.getColumnWidth(2) + "px");
    scwin.setReturnValue("col2 (minWidth=150 / 초기 200) : " + objGrid.getColumnWidth(3) + "px");
    scwin.setReturnValue("col3 (fixColumnWidth=true / 초기 120) : " + objGrid.getColumnWidth(4) + "px");
};
